import {getSession} from "@/lib/auth"; import {query} from "@/lib/db"; import {Brand} from "@/components/Brand"; import {LogoutButton, BackButton} from "@/components/AdminControls";
export default async function Admin(){const s=await getSession();if(!s||s.role!=="admin")return <main className="login-page"><div className="login-card"><Brand/><h1>Admin access</h1><p className="muted">Use your administrator account to continue.</p><a className="btn btn-primary" href="/login">Login</a></div></main>;const [u,c,e,p]=await Promise.all([query(`SELECT COUNT(*)::int count FROM users`),query(`SELECT COUNT(*)::int count FROM courses`),query(`SELECT COUNT(*)::int count FROM enrollments`),query(`SELECT COALESCE(SUM(amount),0)::numeric total FROM payments WHERE status='paid'`)]);return <div className="dashboard"><aside className="sidebar"><Brand/><nav><a className="active">⌂ Dashboard</a><a href="/admin/courses">▦ Courses</a><a>◉ Students</a><a>◉ Teachers</a><a>▶ Videos</a><a>₹ Payments</a><a>☑ Tests</a><a>● Feedback</a><a>◫ Reports</a><a>⚙ Settings</a></nav><LogoutButton/></aside><main className="main"><div className="section-head"><div><span className="eyebrow">ADMIN CONTROL CENTER</span><h1>Dashboard</h1></div><div className="actions"><BackButton/><a className="btn btn-primary" href="/admin/courses/new">+ Add Course</a></div></div><div className="stats"><div className="stat"><div className="icon">👥</div><strong>{u.rows[0].count}</strong><span className="muted">Users</span></div><div className="stat"><div className="icon">📚</div><strong>{c.rows[0].count}</strong><span className="muted">Courses</span></div><div className="stat"><div className="icon">✓</div><strong>{e.rows[0].count}</strong><span className="muted">Enrollments</span></div><div className="stat"><div className="icon">₹</div><strong>₹{Number(p.rows[0].total).toLocaleString('en-IN')}</strong><span className="muted">Revenue</span></div></div><div className="panel" style={{marginTop:20}}><h2>System status</h2><table className="table"><tbody><tr><td>SQLite</td><td>Local SQL database</td><td>✓</td></tr><tr><td>Cloudflare R2</td><td>Private media storage</td><td>✓</td></tr><tr><td>Razorpay</td><td>Payment integration</td><td>Configured by environment</td></tr></tbody></table></div></main></div>}
